response = client.chat.completions.create(
    model="deepseek-v4-pro",
    messages=[{"role": "user", "content": "你好"}],
    stream=True
)
for chunk in response:
    token = chunk.choices[0].delta.content
    if token:
        print(token, end='')

full_reply = ''
for chunk in response:
    token = chunk.choices[0].delta.content
    if token:
        print(token, end='')
        full_reply += token
